//! The Rust tokens against the Swift ones: every colour by role (light and dark), the palette, the radii, the spacing,
//! the shadows and the text styles of `swift/GabaritCommon/GTokens.swift` must be the same here, and the embedded fonts
//! the same files as GabaritApple's. Both are generated by `tools/tokens.py` from one source; this checks the
//! generator's two outputs against each other, read independently.

use std::collections::HashMap;
use std::path::PathBuf;

use gabarit_gpui::tokens::{self, GRgba};

fn repository() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn swift() -> String {
    std::fs::read_to_string(repository().join("swift/GabaritCommon/GTokens.swift"))
        .expect("GTokens.swift")
}

/// The body of `public enum <name> { … }`.
fn block(source: &str, name: &str) -> String {
    let start = source
        .find(&format!("public enum {name} {{"))
        .unwrap_or_else(|| panic!("enum {name}"));
    let rest = &source[start..];
    rest[..rest.find("\n}").unwrap()].to_string()
}

/// `public static let name = value` lines of a block.
fn lets(block: &str) -> Vec<(String, String)> {
    block
        .lines()
        .filter_map(|line| line.trim().strip_prefix("public static let "))
        .filter_map(|line| {
            line.split_once(" = ")
                .or_else(|| line.split_once(": Double = "))
        })
        .map(|(name, value)| {
            (
                name.split(':').next().unwrap().trim().to_string(),
                value.trim().to_string(),
            )
        })
        .collect()
}

fn snake(name: &str) -> String {
    let mut out = String::new();
    let mut previous: Option<char> = None;
    for c in name.chars() {
        if let Some(p) = previous
            && p.is_ascii_lowercase()
            && (c.is_ascii_uppercase() || c.is_ascii_digit())
        {
            out.push('_');
        }
        out.push(c.to_ascii_lowercase());
        previous = Some(c);
    }
    out
}

fn hex(text: &str) -> u32 {
    u32::from_str_radix(text.trim_start_matches("0x"), 16).unwrap()
}

/// `GRGBA(hex: 0x…)`, `GRGBA(hex: 0x…, alpha: a)`, `GPaletteValues.name`, `GPaletteValues.name.opacity(a)`.
fn color(text: &str, palette: &HashMap<String, GRgba>) -> GRgba {
    if let Some(rest) = text.strip_prefix("GRGBA(hex: ") {
        let inner = rest.trim_end_matches(')');
        return match inner.split_once(", alpha: ") {
            Some((h, a)) => GRgba::hexa(hex(h), a.parse().unwrap()),
            None => GRgba::hex(hex(inner)),
        };
    }
    let rest = text
        .strip_prefix("GPaletteValues.")
        .unwrap_or_else(|| panic!("colour {text}"));
    match rest.split_once(".opacity(") {
        Some((name, a)) => palette[name].opacity(a.trim_end_matches(')').parse().unwrap()),
        None => palette[rest],
    }
}

fn close(a: GRgba, b: GRgba) -> bool {
    [
        (a.red, b.red),
        (a.green, b.green),
        (a.blue, b.blue),
        (a.alpha, b.alpha),
    ]
    .iter()
    .all(|(x, y)| (x - y).abs() < 1e-6)
}

#[test]
fn colours_match_swift() {
    let source = swift();
    let palette: HashMap<String, GRgba> = lets(&block(&source, "GPaletteValues"))
        .into_iter()
        .map(|(name, value)| (name, color(&value, &HashMap::new())))
        .collect();
    assert_eq!(palette.len(), 47, "the palette's size");

    let light = tokens::LIGHT.map(|c| c);
    let dark = tokens::DARK.map(|c| c);
    // The Rust roles, by name, through their Debug form (the struct's fields in order).
    let roles = |values: &tokens::GColorValues| -> HashMap<String, GRgba> {
        let debug = format!("{values:?}");
        let mut out = HashMap::new();
        for part in debug.trim_start_matches("GColorRoles { ").split("}, ") {
            let (name, rest) = part.split_once(": GRgba { ").unwrap();
            let numbers: Vec<f32> = rest
                .trim_end_matches(" }")
                .trim_end_matches('}')
                .split(", ")
                .map(|field| {
                    field
                        .split_once(": ")
                        .unwrap()
                        .1
                        .trim_end_matches([' ', '}'])
                        .parse()
                        .unwrap()
                })
                .collect();
            out.insert(
                name.trim().to_string(),
                GRgba {
                    red: numbers[0],
                    green: numbers[1],
                    blue: numbers[2],
                    alpha: numbers[3],
                },
            );
        }
        out
    };
    let (light, dark) = (roles(&light), roles(&dark));
    let swift_roles = lets(&block(&source, "GColorValues"));
    assert_eq!(swift_roles.len(), light.len(), "the same roles");
    for (name, value) in swift_roles {
        let pair = value
            .strip_prefix("GColorPair(light: ")
            .unwrap()
            .strip_suffix(')')
            .unwrap();
        let (l, d) = pair.split_once(", dark: ").unwrap();
        let rust = snake(&name);
        assert!(close(light[&rust], color(l, &palette)), "{name}, light");
        assert!(close(dark[&rust], color(d, &palette)), "{name}, dark");
    }
}

#[test]
fn geometry_matches_swift() {
    let source = swift();
    let number = |value: &str| value.parse::<f32>().unwrap();
    let radius: HashMap<_, _> = lets(&block(&source, "GRadius")).into_iter().collect();
    assert_eq!(number(&radius["sm"]), tokens::radius::SM);
    assert_eq!(number(&radius["md"]), tokens::radius::MD);
    assert_eq!(number(&radius["lg"]), tokens::radius::LG);
    assert_eq!(number(&radius["pill"]), tokens::radius::PILL);
    let spacing: HashMap<_, _> = lets(&block(&source, "GSpacing")).into_iter().collect();
    assert_eq!(number(&spacing["xs"]), tokens::spacing::XS);
    assert_eq!(number(&spacing["xxl"]), tokens::spacing::XXL);
    assert_eq!(number(&spacing["xxxxxl"]), tokens::spacing::XXXXXL);
    let opacity: HashMap<_, _> = lets(&block(&source, "GOpacity")).into_iter().collect();
    assert_eq!(number(&opacity["disabled"]), tokens::opacity::DISABLED);

    let shadows: HashMap<_, _> = lets(&block(&source, "GShadowValues")).into_iter().collect();
    for (name, rust) in [
        ("card", tokens::shadows::CARD),
        ("bar", tokens::shadows::BAR),
        ("raised", tokens::shadows::RAISED),
        ("floating", tokens::shadows::FLOATING),
    ] {
        let value = &shadows[name];
        let field = |key: &str| {
            let start = value.find(&format!(", {key}: ")).unwrap() + key.len() + 4;
            number(value[start..].split([',', ')']).next().unwrap())
        };
        assert_eq!(field("radius"), rust.radius, "{name}'s radius");
        assert_eq!(
            (field("x"), field("y")),
            (rust.x, rust.y),
            "{name}'s offset"
        );
    }
}

#[test]
fn text_styles_match_swift() {
    let source = swift();
    let styles = lets(&block(&source, "GTextStyles"));
    let rust = [
        ("largeTitle", tokens::text::LARGE_TITLE),
        ("title", tokens::text::TITLE),
        ("title2", tokens::text::TITLE_2),
        ("title3", tokens::text::TITLE_3),
        ("headline", tokens::text::HEADLINE),
        ("subheadline", tokens::text::SUBHEADLINE),
        ("body", tokens::text::BODY),
        ("callout", tokens::text::CALLOUT),
        ("footnote", tokens::text::FOOTNOTE),
        ("caption", tokens::text::CAPTION),
        ("caption2", tokens::text::CAPTION_2),
        ("mono", tokens::text::MONO),
    ];
    assert_eq!(styles.len(), rust.len());
    for ((name, value), (rust_name, style)) in styles.iter().zip(rust) {
        assert_eq!(name, rust_name);
        let expected = format!(
            "GTextStyle(family: .{}, weight: .{}, phone: {}, desktop: {}, system: \"{}\")",
            format!("{:?}", style.family).to_lowercase(),
            format!("{:?}", style.weight).to_lowercase(),
            style.phone,
            style.desktop,
            style.system
        );
        assert_eq!(value, &expected, "{name}");
    }
}

#[test]
fn fonts_are_apples() {
    let apple = repository().join("swift/GabaritApple/Resources/Fonts");
    for (file, bytes) in tokens::FONT_FILES {
        let original =
            std::fs::read(apple.join(file)).unwrap_or_else(|_| panic!("{file} in GabaritApple"));
        assert!(original == *bytes, "{file} differs from GabaritApple's");
    }
}
